const fs = require('fs');

const file = 'src/data/textbookData.ts';
let content = fs.readFileSync(file, 'utf8');

function updateChapter(chapId, newSections) {
  const startIdx = content.indexOf(`"id": "${chapId}"`);
  if (startIdx === -1) {
    console.error(`Chapter ID ${chapId} not found!`);
    return false;
  }
  
  const sectionsKeyIdx = content.indexOf(`"sections": [`, startIdx);
  if (sectionsKeyIdx === -1) {
    console.error(`sections array not found for ${chapId}`);
    return false;
  }
  
  let depth = 0;
  let arrayStartIdx = content.indexOf('[', sectionsKeyIdx);
  let arrayEndIdx = -1;
  
  for (let i = arrayStartIdx; i < content.length; i++) {
    if (content[i] === '[') depth++;
    else if (content[i] === ']') {
      depth--;
      if (depth === 0) {
        arrayEndIdx = i;
        break;
      }
    }
  }
  
  if (arrayEndIdx === -1) {
    console.error(`Could not find closing ] for sections in ${chapId}`);
    return false;
  }
  
  const sectionsJson = JSON.stringify(newSections, null, 8);
  content = content.slice(0, arrayStartIdx) + sectionsJson + content.slice(arrayEndIdx + 1);
  console.log(`Successfully updated sections for ${chapId}`);
  return true;
}

